BODY='''<body><a class="skip" href="#work">作品へ移動</a><header class="header wrap"><a class="brand" href="../index.html">LUMINOUS / STUDIES</a><nav aria-label="ページの案内"><a href="../kinetic-observatory/index.html">光の粒子の立体変形 ↗</a><a href="../index.html">作品一覧 ↗</a></nav></header><main class="wrap"><section class="intro" aria-labelledby="title"><div><p class="eyebrow">LIGHT SCULPTURE No.02 / CONTINUOUS CURRENTS</p><h1 id="title">光の<span>潮汐。</span></h1></div><p class="intro-copy">流れは、かたちをほどき続ける。<br>青緑、琥珀、菫色。三つの光の帯が交差し、<br>呼吸するように、ひとつの立体を編んでいく。</p></section><p class="reduced-note">「動きを減らす」設定に合わせて静止表示しています。色の層と粒子密度は選べます。</p><section class="work" id="work" aria-label="光の潮汐の鑑賞と操作"><input class="input" type="checkbox" id="pause" aria-label="動きを一時停止"><input class="input" type="radio" name="layer" id="all" checked aria-label="三つの帯を表示"><input class="input" type="radio" name="layer" id="cyan" aria-label="青緑の帯を表示"><input class="input" type="radio" name="layer" id="gold" aria-label="琥珀の帯を表示"><input class="input" type="radio" name="layer" id="violet" aria-label="菫色の帯を表示"><input class="input" type="checkbox" id="sparse" checked aria-label="軽量表示、192粒にする"><div class="stage" role="img" aria-label="384個の丸い光粒子が、青緑、琥珀、菫色の三本の立体的な帯を描く。粒子は帯に沿って異なる方向と速さで流れ、帯全体も前後に揺れながら膨張・収縮する。"><div class="meta" aria-hidden="true"><span>VOLUME / 02<small>THREE INTERWOVEN CURRENTS</small></span><span><span class="full-count">384 LIGHTS</span><span class="light-count">192 LIGHTS / LITE</span><br>23s / 29s / 37s</span></div><div class="scene" aria-hidden="true"><div class="scale"><div class="camera motion"><div class="tilt">__BANDS__</div></div></div></div><div class="legend" aria-hidden="true"><span style="--c:#68f5e4">JADE</span><span style="--c:#ffd28c">AMBER</span><span style="--c:#c8a3ff">IRIS</span></div><span class="signature" aria-hidden="true">LIGHT HAS A MEMORY OF MOTION.</span></div><div class="toolbar"><div class="group" role="group" aria-label="表示する光の帯"><span class="title">光の層</span><label for="all">すべて</label><label for="cyan">青緑</label><label for="gold">琥珀</label><label for="violet">菫色</label></div><label for="sparse">軽量表示（192粒）</label><label for="pause" class="pause"><span class="playing">Ⅱ 動きを止める</span><span class="resume">▷ 動きを再開</span></label></div></section><div class="caption"><p>交差する光、ほどける奥行き。ひとつの形の中で、三つの時間が流れ続けます。</p><span>THREE CURRENTS / ONE SCULPTURE</span></div><details class="notes"><summary>作品の構造と、観察のヒント</summary><p>三葉結び目の曲線に沿って、幅を持つ三本の帯を配置しています。各帯は4列×32粒の128粒。合計384粒が、23秒・29秒・37秒の異なる周期で軌道を巡り、琥珀の流れだけが逆向きに進みます。手前の粒は大きく濃く、奥の粒は小さく薄く描きます。奥行きと視点の計算はHTML生成時に行い、前後が入れ替わると大きさと透明度も変わります。明るい粒を追うと、形の中を光が移動する様子を観察できます。</p><p>帯の膨張・収縮は11秒・13秒・17秒、全体の回転は36秒です。これらが重なるため、同じ形でも前後の重なりや隙間が変わり続けます。色の層を一つずつ選んで見ることもできます。色の層の切替では時間を保ちます。間引いた粒子は描画とアニメーションを停止し、密度を戻すと初期位相から再開します。</p><p>Tabで操作を選び、Spaceで停止・再開・粒子密度を切り替えます。色の層は矢印キーでも選択できます。設定は保存しません。端末の「動きを減らす」設定と印刷では静止表示します。</p><p>軌道はPython標準ライブラリで作成時に計算し、HTML内のCSSだけで再生します。JavaScript・外部画像・外部フォント・追加パッケージは不要です。再生成は <code>python3 tools/generate_luminous_tides.py</code>。実行中の物理計算ではなく、決められた軌道を描く作品です。</p></details></main><footer class="footer wrap"><a href="../index.html">← 作品一覧</a><span>Luminous Tides / 光の潮汐</span><a href="../kinetic-observatory/index.html">光の粒子の立体変形 ↗</a></footer></body></html>'''
def build():
    css=[];bands=[]
    for band in range(3):
        dots=[];duration=(23,29,37)[band]
        for lane in range(LANES):
            name=f'flow-{band}-{lane}';frames=[]
            for k in range(STEPS+1):
                t=TAU*k/STEPS;x,y,z=projected(point(t,band,lane))
                size_factor,opacity=sample_depth(z)
                frames.append(f'{k/STEPS*100:.5f}%{{transform:translate3d({x:.3f}px,{y:.3f}px,{z:.3f}px) scale({size_factor:.4f});opacity:{opacity:.4f}}}')
            assert all(abs(a-b)<1e-8 for a,b in zip(point(0,band,lane),point(TAU,band,lane)))
            assert frames[0].split('{',1)[1] == frames[-1].split('{',1)[1], 'Loop seam must match'
            css.append('@keyframes '+name+'{'+''.join(frames)+'}')
            for j in range(SAMPLES):
                phase=(j+lane/LANES)/SAMPLES;x,y,z=projected(point(TAU*phase,band,lane));size_factor,opacity=sample_depth(z)
                kind='beacon' if j%16==0 and lane%4==0 else 'soft' if lane%3 else ''
                size=2.4+(lane%5)*.22+(1.2 if kind=='beacon' else 0)
                dots.append(f'<i class="dot motion {kind} {"secondary" if (j+lane)%2 else ""}" style="--path:{name};--duration:{duration}s;--delay:{-duration*phase:.5f}s;--size:{size:.2f}px;--alpha:{opacity:.4f};--rest:translate3d({x:.3f}px,{y:.3f}px,{z:.3f}px) scale({size_factor:.4f})"></i>')
        bands.append(f'<div class="band motion {("cyan","gold","violet")[band]}" style="--color:{COLORS[band]};--breath:{(11,13,17)[band]}s;--offset:{-band*3}s">'+ '\n'.join(dots)+'</div>')
    css.append('.light-count{display:none}#sparse:checked~.stage .light-count{display:inline}#sparse:checked~.stage .full-count{display:none}')
    css.append('.dot,.dot.beacon{width:calc(var(--size)*2.6);height:calc(var(--size)*2.6);margin:calc(var(--size)*-1.3);background:radial-gradient(circle,#fff 0 8%,currentColor 16% 27%,transparent 72%);box-shadow:none!important}@keyframes tidal-sway{0%,100%{transform:rotateY(-13deg) rotateX(-5deg)}50%{transform:rotateY(13deg) rotateX(5deg)}}@media(prefers-reduced-motion:reduce){.tilt{transform:none}}@media print{.tilt{transform:none}.dot{background:currentColor}}')
    html='<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="384個の光粒子が三つの立体的な帯を編む、独立したHTML＋CSS作品。"><title>Luminous Tides｜光の潮汐</title><style>'+CSS+'\n'.join(css)+'</style></head>'+BODY.replace('__BANDS__','\n'.join(bands))
    assert html.count('class="dot motion ')==384
    assert '<script' not in html
    target=Path(__file__).resolve().parent.parent/'works'/'luminous-tides/index.html';target.parent.mkdir(exist_ok=True);target.write_text(html)
    print(f'Verified 12 closed paths and 384 particles; {len(html.encode()):,} bytes.')
if __name__=='__main__':build()
